<?php
use App\Models\PaymentTransaction; use Illuminate\Support\Facades\Gate; use Livewire\Attributes\Title; use Livewire\Component; use Livewire\WithPagination;
new #[Title('Payment Transactions')] class extends Component { use WithPagination; public string $search=''; public string $status=''; public function mount():void{Gate::authorize('viewAny',PaymentTransaction::class);} public function transactions(){return PaymentTransaction::with('donation:id,reference')->when($this->search,fn($q)=>$q->where(fn($q)=>$q->where('provider_reference','like','%'.$this->search.'%')->orWhereHas('donation',fn($q)=>$q->where('reference','like','%'.$this->search.'%'))))->when($this->status,fn($q)=>$q->where('status',$this->status))->latest()->paginate(20);} }; ?>
<div class="mx-auto w-full max-w-7xl space-y-6"><x-admin.page-header :title="__('Payment transactions')" :description="__('Provider-neutral transaction history without sensitive payment credentials.')" :eyebrow="__('Giving management')"/><section class="overflow-hidden rounded-xl border bg-white dark:border-zinc-800 dark:bg-zinc-900"><div class="p-4"><flux:input wire:model.live.debounce.300ms="search" :label="__('Search reference')"/></div><table class="w-full text-sm"><thead><tr><th class="px-5 py-3 text-left">{{__('Donation')}}</th><th class="px-5 py-3">{{__('Provider')}}</th><th class="px-5 py-3">{{__('Amount')}}</th><th class="px-5 py-3">{{__('Status')}}</th><th class="px-5 py-3">{{__('Date')}}</th></tr></thead><tbody>@forelse($this->transactions() as $t)<tr class="border-t dark:border-zinc-800"><td class="px-5 py-4">{{$t->donation?->reference??'—'}}</td><td class="px-5 py-4 text-center">{{$t->provider??__('Manual')}}<p class="font-mono text-xs">{{$t->provider_reference}}</p></td><td class="px-5 py-4 text-center">{{$t->currency}} {{number_format((float)$t->amount,2)}}</td><td class="px-5 py-4 text-center">{{$t->status->label()}}</td><td class="px-5 py-4 text-center">{{$t->created_at->format('M j, Y')}}</td></tr>@empty<tr><td colspan="5" class="p-10 text-center text-slate-500">{{__('No transactions recorded.')}}</td></tr>@endforelse</tbody></table><div class="p-4">{{$this->transactions()->links()}}</div></section></div>
